# Enemy / wildlife reactions (2026-11-27 pass 2): alert = the moment it spots the player, idle = rare voice nearby.
for _fam, _name in [("enemy.slime", "Slime"), ("enemy.goblin", "Goblin"), ("enemy.ent", "Ent"),
                    ("wildlife.boar", "Boar"), ("wildlife.deer", "Deer"), ("wildlife.rabbit", "Rabbit")]:
    SETTINGS[f"sfx.{_fam}_alert"] = dict(cat='Combat', vol=1.0, jitter=0.06, cooldown=0.3, voices=2, loop=False,
                                          desc=f"{_name} notices the player")
    if _name != "Rabbit":
        SETTINGS[f"sfx.{_fam}_idle"] = dict(cat='Combat', vol=1.0, jitter=0.08, cooldown=0.8, voices=2, loop=False,
                                             desc=f"{_name} idle voice (rare, only near the player)")

# Volume pass 2026-11-27: measured in game (SfxMixProbe), an AoE hitting 8 enemies stacked 8 identical hurt sounds
# (about +9 dB). Cap simultaneous voices of every crowd sound so mass hits stay readable instead of noisy.
CROWD_VOICES = {
    "sfx.combat.enemy_hit": 3, "sfx.combat.enemy_death": 3, "sfx.combat.hit_impact": 3, "sfx.combat.unarmed_hit": 3,
    "sfx.skill.hit_flesh": 3, "sfx.world.loot_drop": 2,
    "sfx.enemy.slime_hurt": 3, "sfx.enemy.slime_death": 3, "sfx.enemy.slime_attack": 2,
    "sfx.enemy.goblin_hurt": 3, "sfx.enemy.goblin_death": 3, "sfx.enemy.goblin_attack": 2,
    "sfx.enemy.ent_hurt": 2, "sfx.enemy.ent_death": 2, "sfx.enemy.ent_attack": 2,
    "sfx.wildlife.deer_hurt": 2, "sfx.wildlife.deer_death": 2, "sfx.wildlife.boar_hurt": 2, "sfx.wildlife.boar_death": 2,
    "sfx.wildlife.boar_attack": 2, "sfx.wildlife.rabbit_hurt": 2, "sfx.wildlife.rabbit_death": 2,
    "sfx.skill.earth_s1_impact": 3, "sfx.skill.water_s1_impact": 3, "sfx.skill.earth_s2_spike": 3,
    "sfx.skill.wind_s2_land": 3, "sfx.skill.wind_s3_wall_slam": 3,
}
for _id, _v in CROWD_VOICES.items():
    SETTINGS[_id]["voices"] = _v
# Deaths had no cooldown: 6 goblins dying in the same frame measured +6 dB over one. A 60 ms window merges them.
for _id in [k for k in SETTINGS if k.endswith("_death") and ("enemy" in k or "wildlife" in k)] + ["sfx.combat.enemy_death"]:
    SETTINGS[_id]["cooldown"] = max(SETTINGS[_id]["cooldown"], 0.06)
